import{_ as l,a0 as u,w as i,s as d,ao as p,I as o,a1 as n,A as r,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const R=JSON.parse('{"title":"如何在linux上通过GRUB添加内核参数 | LCTT x X-CMD","titleTemplate":false,"description":"如何在linux上通过GRUB添加内核参数 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在linux上通过GRUB添加内核参数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在linux上通过GRUB添加内核参数 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to add kernel boot parameters via GRUB on Linux","title":"如何在linux上通过GRUB添加内核参数","tag":"201311","desc":""},"relativePath":"201311/How to add kernel boot parameters via GRUB on Linux.md","filePath":"[post].md"}'),s={name:"201311/How to add kernel boot parameters via GRUB on Linux.md"};function m(b,e,f,x,g,U){const a=u("Link");return i(),d("div",null,[e[12]||(e[12]=p(`<h1 id="如何在linux上通过grub添加内核参数" tabindex="-1">如何在linux上通过GRUB添加内核参数 <a class="header-anchor" href="#如何在linux上通过grub添加内核参数" aria-label="Permalink to “如何在linux上通过GRUB添加内核参数”">​</a></h1><p>我们可以在linux内核启动时为其提供各种各样的参数。这些参数可以自定义内核默认的行为，或者通知内核关于硬件的配置信息。内核参数应在内核启动时通过引导装载程序，如GRUB或LILO传递给内核。</p><p>在本教程中，我将会描述<strong>如何在linux上通过GRUB添加内核参数</strong>。</p><p>如果你在使用GRUB引导装载程序，想修改或添加内核参数，你可以编辑GRUB配置文件。下面是针对特定发行版在GRUB的配置文件中添加内核启动参数的方法。</p><h3 id="在debian或ubuntu上添加内核启动参数" tabindex="-1">在Debian或Ubuntu上添加内核启动参数### <a class="header-anchor" href="#在debian或ubuntu上添加内核启动参数" aria-label="Permalink to “在Debian或Ubuntu上添加内核启动参数###”">​</a></h3><p>在基于Debian的系统上，如果你想在系统启动时添加内核参数，你可以编辑 /etc/default/grub 目录下的GRUB配置模板。在 GRUB_CMDLINE_LINUX_DEFAULT 变量中以 “name=value” 的格式添加内核参数。</p><pre><code>$ sudo -e /etc/default/grub 
</code></pre><blockquote><p>GRUB_CMDLINE_LINUX_DEFAULT=&quot;...... name=value&quot;</p></blockquote><p>然后运行下面的命令来生成一个GRUB的配置文件。</p><pre><code>$ sudo update-grub 
</code></pre><p>如果无法找到 update-grub 命令，你可以通过下面的命令安装它。</p><pre><code>$ sudo apt-get install grub2-common 
</code></pre><h3 id="在fedora上添加内核启动参数" tabindex="-1">在Fedora上添加内核启动参数 <a class="header-anchor" href="#在fedora上添加内核启动参数" aria-label="Permalink to “在Fedora上添加内核启动参数”">​</a></h3><p>在Fedora上，想要在启动时添加内核参数，你可以编辑 /etc/default/grub目录下的 GRUB 配置模板。在 GRUB_CMDLINE_LINUX 变量中以 “name=value” 的格式添加内核参数。</p><pre><code>$ sudo -e /etc/default/grub 
</code></pre><blockquote><p>GRUB_CMDLINE_LINUX=&quot;...... name=value&quot;</p></blockquote><p>然后运行下面的命令生成 GRUB2 配置文件。</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg
</code></pre><h3 id="在centos上添加内核启动参数" tabindex="-1">在CentOS上添加内核启动参数 <a class="header-anchor" href="#在centos上添加内核启动参数" aria-label="Permalink to “在CentOS上添加内核启动参数”">​</a></h3><p>在CentOS上，想要在启动时添加内核参数，你可以直接编辑GRUB配置文件 /boot/grub/grub.conf。在配置文件中，找到描述默认使用的Linux映像的条目。文件中最顶行的字符串 “default=N”会指示哪一个条目是默认的映像。</p>`,20)),o("p",null,[n(a,{href:"http://www.flickr.com/photos/xmodulo/10618657834/"},{default:r(()=>[...e[0]||(e[0]=[o("img",{src:"http://farm8.staticflickr.com/7429/10618657834_8082c2806b_z.jpg",alt:""},null,-1)])]),_:1})]),e[13]||(e[13]=o("p",null,"找到默认的映像条目后，在以 “kernel /vmlinuz-” 开头的那一段的结尾附加上内核参数。参数的格式为 “name=value” 。",-1)),e[14]||(e[14]=o("hr",null,null,-1)),o("p",null,[e[2]||(e[2]=t("via: ",-1)),n(a,{href:"http://xmodulo.com/2013/11/add-kernel-boot-parameters-via-grub-linux.html"},{default:r(()=>[...e[1]||(e[1]=[t("http://xmodulo.com/2013/11/add-kernel-boot-parameters-via-grub-linux.html",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("译者：",-1)),n(a,{href:"https://github.com/Linchenguang"},{default:r(()=>[...e[3]||(e[3]=[t("Linchenguang",-1)])]),_:1}),e[6]||(e[6]=t(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[9]||(e[9]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[7]||(e[7]=[t("LCTT",-1)])]),_:1}),e[10]||(e[10]=t(" 原创翻译，",-1)),n(a,{href:"http://linux.cn/"},{default:r(()=>[...e[8]||(e[8]=[t("Linux中国",-1)])]),_:1}),e[11]||(e[11]=t(" 荣誉推出",-1))])])}const G=l(s,[["render",m]]);export{R as __pageData,G as default};
